// Parse the runner's response (already-parsed JSON) into the structured
// summary fields the digest email + branching can consume. The runner shape:
//   { exit_code, duration_ms, timed_out, stdout_json, stdout_raw, stderr_tail }
// On a clean run, stdout_json IS the Python summary. On a parse / timeout /
// runner error, stdout_json is null and we fall into a parse-error branch.
const item = $input.first();
const r = item.json || {};
const exitCode = r.exit_code != null ? r.exit_code : -1;
const stderrTail = (r.stderr_tail || '').toString();
const summary = r.stdout_json;

if (!summary) {
  let parseError;
  if (r.timed_out) {
    parseError = `runner_timeout_after_${r.duration_ms || 0}ms`;
  } else if (exitCode !== 0) {
    parseError = `runner_exit_code_${exitCode}_with_no_parsed_stdout`;
  } else {
    parseError = 'runner_returned_null_stdout_json';
  }
  return [{ json: {
    top_status: 'parse_error',
    parse_failure: 'python_stdout_unparseable',
    parse_error: parseError,
    exitCode,
    raw_stderr: stderrTail.slice(0, 1000),
    raw_stdout: ((r.stdout_raw || '').toString()).slice(0, 500),
    files_discovered: 0, files_with_content: 0,
    tasks_written: 0, notes_written: 0, articles_queued: 0,
    files_extracted: [], files_partial: [], files_error: [],
    files_by_state: { empty: 0, has_content: 0, scanning: 0, extracted: 0, partial: 0, error: 0 },
    reset_summary: { files_reset_full: 0, files_reset_partial: 0, files_reset_skipped: 0 },
  }}];
}

// Compute a coarse top-level status for the email branch.
const byState = summary.files_by_state || {};
const hasError = (byState.error || 0) > 0 || (summary.errors || []).length > 0;
const hasWork = (summary.files_with_content || 0) > 0;
let topStatus;
if (hasError) {
  topStatus = 'partial_or_error';
} else if (!hasWork) {
  topStatus = 'no_work';
} else {
  topStatus = 'success';
}

return [{ json: {
  ...summary,
  exitCode,
  raw_stderr_tail: stderrTail.split('\n').slice(-20).join('\n'),
  top_status: topStatus,
}}];
